        victimRelief: {
            q: '피해자 구제안이 필요한가?',
            a: '필요하다. 검사의 직접수사·직접 보완수사가 폐지되면 사건이 경찰 수사 중심으로 이동해 부실수사·불송치·불기소로 피해자 권리가 약화될 위험이 커진다. 따라서 불송치 이의신청(제245조의7)·재수사요청(제245조의8)·불기소 재정신청(제260조)·처분 통지·기록 열람 같은 사후 구제 통로가 반드시 강화되어야 한다. 김용민·박은정 의원안은 재정신청을 대폭 정비하고 공소심의회 심의와 연계해 이를 두텁게 설계했다. 더불어민주당 검찰개혁 TF안은 상대적으로 약하다(공소심의회 없음).',
        },
        ombudsman: {
            q: '평소 감시·견제하는 「시민옴부즈만」 제도가 필요한가?',
            a: '필요하다. 피해자 구제(이의신청·재정신청)는 피해가 발생하고 처분이 난 뒤 당사자가 신청해야 작동하는 「사후·개별」 구제다. 반면 시민옴부즈만은 특정 사건 당사자가 아니어도 주권자인 시민이 수사·기소권 행사 전반을 「평소·상시」 감시하고 시정을 요구하는 시스템적 견제다. 두 형소법 개정안에는 옴부즈만·상시 시민감시 기구가 없다(김용민·박은정 의원안의 수사인권보호관은 수사기관 내부 인권 담당, 공소심의회는 기소 심의로, 독립적 시민 옴부즈만이 아니다). 주권자사법개혁추진준비위원회 안의 「사법감시이중안전법」(사법감찰관+사법옴부즈만)이 상시 감시 기능을 담당한다.',
        },
        conclusion: '「사후 구제(피해자 구제) + 상시 감시(시민옴부즈만)」의 병행이 필요하다. 사후 구제만으로는 권력 남용을 사전에 억제하지 못하고, 상시 감시가 없으면 남용이 반복된다. 헌법 제1조(주권재민)가 요구하는 것은 주권자인 국민이 수사·기소 권력을 「평소에」 통제하는 것이며, 시민옴부즈만은 그 상시적 통제의 핵심 장치다.',
        note: '※ 수사심의회(수사 단계 심의 기구)는 두 개정안 모두 두지 않는다. 김용민·박은정 의원안에는 「공소심의회」(기소 여부 심의, 제246조의3)만 있다. 현행 대검찰청 「수사심의위원회」는 검찰 내부 자문기구로 이 법안들의 공식 기구와 별개다.',
