                    lesson: '검사가 수사권을 잃은 뒤 남은 유일한 핵심 권한이 기소권이라면, 그 권한에 대한 시민 통제는 오히려 더 두터워져야 한다. 그런데 통과안은 재정신청의 문을 조금 열었을 뿐이고, 열린 문마저 신고의무자에게만 허용했다. 권한이 좁아질수록 통제는 촘촘해져야 한다는 원칙이 지켜지지 않았다.',
